#include "metalrobo/MetalUnifiedQualitySolver.hpp"
#include <array>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <limits>
#include <vector>
using namespace metalrobo;
MRUnifiedQualityBlockGPU block(unsigned row,bool hard){MRUnifiedQualityBlockGPU b{};b.layout={row,1,MR_UNIFIED_QUALITY_SCALAR_INTERVAL,hard?MR_UNIFIED_QUALITY_BLOCK_HARD_EQUALITY:0u};b.stableKey={500+row,0,0,0};b.scale0=b.scale1={1,1,1,1};b.regularization0=b.regularization1={.02f,1,1,1};b.boundsAndShift={hard?-std::numeric_limits<float>::max():0.0f,std::numeric_limits<float>::max(),0,0};return b;}
int main(){std::cout<<std::setprecision(17);for(int mode=0;mode<4;++mode){bool contradiction=mode==3;std::vector<MRUnifiedQualityBlockGPU> blocks{block(0,true),block(1,contradiction)};if(contradiction)blocks.push_back(block(2,false));std::vector<float>A=mode==2?std::vector<float>{1,.5f,.5f,1}:std::vector<float>{1,0,0,1};std::vector<float>J=contradiction?std::vector<float>{1,0,1,0,0,1}:std::vector<float>{1,0,0,1};std::vector<float>bias=contradiction?std::vector<float>{-.1f,-.2f,.2f}:std::vector<float>{-.1f,mode==1?.2f:-.2f};std::vector<float>zv(2,0),zl(blocks.size(),0);MetalUnifiedQualityProblem p;p.problemCount=1;p.generalizedVelocityCount=2;p.rowCount=blocks.size();p.blocks=blocks;p.dynamics=A;p.jacobian=J;p.bias=bias;p.freeVelocity=zv;p.warmVelocity=zv;p.warmImpulses=zl;MetalUnifiedQualityConfig c;c.maximumNewtonIterations=40;c.optimalityTolerance=1e-5f;c.feasibilityTolerance=2e-5f;c.directMaximumGeneralizedVelocities=64;MetalUnifiedQualityResult result;result.velocity={123};result.impulses={456};auto d=solveMetalUnifiedQuality(p,result,c);std::cout<<"{\"mode\":"<<mode<<",\"succeeded\":"<<(d.succeeded()?"true":"false")<<",\"dispatched\":"<<(d.dispatched?"true":"false")<<",\"published\":"<<(d.published?"true":"false")<<",\"status\":"<<d.firstGPUStatusCode<<",\"message\":"<<std::quoted(d.message)<<",\"velocity\":[";for(size_t i=0;i<result.velocity.size();++i){if(i)std::cout<<',';std::cout<<result.velocity[i];}std::cout<<"],\"impulses\":[";for(size_t i=0;i<result.impulses.size();++i){if(i)std::cout<<',';std::cout<<result.impulses[i];}std::cout<<"]}"<<std::endl;}return 0;}
